#define FL_HIP   0
#define FL_KNEE  1
#define FR_HIP   2
#define FR_KNEE  3
#define RL_HIP   4
#define RL_KNEE  5
#define RR_HIP   6
#define RR_KNEE  7

#define STEP_DELAY_MS 250

struct MotionTable {
  const char* name;
  const int (*rows)[8];
  int rowCount;
  int repeatCount;
};

void writeServoAngle(int servoIndex, int angle) {
  // ----------------------------------------------------------
  // Replace this body if your OpenCat firmware uses a different
  // servo-write function.
  // ----------------------------------------------------------
#ifdef ESP_PWM
  servo[servoIndex].write(angle);
#else
  pwm.writeAngle(servoIndex, angle);
#endif
}

void applyMotionRow(const int row[8]) {
  writeServoAngle(FL_HIP,  row[0]);
  writeServoAngle(FL_KNEE, row[1]);
  writeServoAngle(FR_HIP,  row[2]);
  writeServoAngle(FR_KNEE, row[3]);
  writeServoAngle(RL_HIP,  row[4]);
  writeServoAngle(RL_KNEE, row[5]);
  writeServoAngle(RR_HIP,  row[6]);
  writeServoAngle(RR_KNEE, row[7]);
}

